// Task-specific Tensor-Core SpMM kernel: Janna_CoupCons3D, K = 32.
// Generated by experiments/tc_custom_spmm/gen_task_kernel.py (2026-08-12)
// from the measured best configuration of the hand-tuned TC kernel family.
//
// Matrix: 416800 x 416800, nnz 22322336 (condensed-tile density 0.3842, BSR fill 4.62)
// Config: scheme=condensed prec=3xtf32 k-tiles/warp=1 warps/block=4
//         chunk=64 sort=1   measured speedup vs cuSPARSE: 3.012
//
// Contract: spmm_preprocess (untimed) / spmm_compute (timed) / spmm_cleanup.

#include <cuda_runtime.h>
#include <mma.h>

#include <algorithm>
#include <cstdio>
#include <cstring>
#include <vector>

using namespace nvcuda;

#define TCK_CHECK(call)                                                     \
    do {                                                                    \
        cudaError_t _e = (call);                                            \
        if (_e != cudaSuccess)                                              \
            fprintf(stderr, "CUDA error %s at %s:%d\n",                     \
                    cudaGetErrorString(_e), __FILE__, __LINE__);            \
    } while (0)

static const int TC_K   = 32;    // dense-matrix width, fixed for this task
static const int TC_KT  = 1;   // 16-wide K slices per warp
static const int TC_WPB = 4;  // warps per block

// 3xTF32 Markidis split (hi*hi + hi*lo + lo*hi): near-FP32 accuracy for
// this matrix's large dynamic range.
template <class CF, class AF, class BF>
__device__ __forceinline__ void tc_mma(CF& acc, AF a, BF b) {
    AF a_lo;
    BF b_lo;
    #pragma unroll
    for (int i = 0; i < a.num_elements; i++) {
        float hi = wmma::__float_to_tf32(a.x[i]);
        a_lo.x[i] = wmma::__float_to_tf32(a.x[i] - hi);
        a.x[i] = hi;
    }
    #pragma unroll
    for (int i = 0; i < b.num_elements; i++) {
        float hi = wmma::__float_to_tf32(b.x[i]);
        b_lo.x[i] = wmma::__float_to_tf32(b.x[i] - hi);
        b.x[i] = hi;
    }
    wmma::mma_sync(acc, a, b_lo, acc);
    wmma::mma_sync(acc, a_lo, b, acc);
    wmma::mma_sync(acc, a, b, acc);
}

struct TaskCtx {
    int num_rows, num_cols, nnz;
    int num_jobs = 0;
    int* d_job_owner = nullptr;
    int* d_job_lo = nullptr;
    int* d_job_hi = nullptr;
    int* d_job_atomic = nullptr;
    int* d_tile_cols;
    float* d_tile_vals;
};


static void build_jobs(TaskCtx* ctx, const std::vector<int>& ptr) {
    const int n = (int)ptr.size() - 1;
    std::vector<int> jo, jl, jh, ja;
    for (int i = 0; i < n; i++) {
        int lo = ptr[i], hi = ptr[i + 1];
        if (hi - lo <= 64) {
            jo.push_back(i); jl.push_back(lo); jh.push_back(hi);
            ja.push_back(0);
        } else {
            for (int s = lo; s < hi; s += 64) {
                jo.push_back(i); jl.push_back(s);
                jh.push_back(std::min(s + 64, hi));
                ja.push_back(1);
            }
        }
    }
    // longest job first: stragglers start at launch, not at the tail
    {
        std::vector<int> order(jo.size());
        for (size_t i = 0; i < order.size(); i++) order[i] = (int)i;
        std::sort(order.begin(), order.end(), [&](int a, int b) {
            return jh[a] - jl[a] > jh[b] - jl[b];
        });
        std::vector<int> jo2, jl2, jh2, ja2;
        for (int i : order) {
            jo2.push_back(jo[i]); jl2.push_back(jl[i]); jh2.push_back(jh[i]);
            ja2.push_back(ja[i]);
        }
        jo.swap(jo2); jl.swap(jl2); jh.swap(jh2); ja.swap(ja2);
    }

    ctx->num_jobs = (int)jo.size();
    size_t bytes = jo.size() * sizeof(int);
    TCK_CHECK(cudaMalloc(&ctx->d_job_owner, bytes));
    TCK_CHECK(cudaMalloc(&ctx->d_job_lo, bytes));
    TCK_CHECK(cudaMalloc(&ctx->d_job_hi, bytes));
    TCK_CHECK(cudaMemcpy(ctx->d_job_owner, jo.data(), bytes, cudaMemcpyHostToDevice));
    TCK_CHECK(cudaMemcpy(ctx->d_job_lo, jl.data(), bytes, cudaMemcpyHostToDevice));
    TCK_CHECK(cudaMemcpy(ctx->d_job_hi, jh.data(), bytes, cudaMemcpyHostToDevice));
    TCK_CHECK(cudaMalloc(&ctx->d_job_atomic, bytes));
    TCK_CHECK(cudaMemcpy(ctx->d_job_atomic, ja.data(), bytes, cudaMemcpyHostToDevice));
}


// Preprocess: group rows in 16-row windows, condense each window's
// distinct columns, pack values into dense 16x8 tiles (row-major).
static void build_condensed(TaskCtx* ctx, const int* h_row_ptr,
                            const int* h_col_ind, const float* h_values) {
    const int rows = ctx->num_rows;
    const int nw = (rows + 15) / 16;

    std::vector<int> tiles_per_win(nw);
    std::vector<std::vector<int>> win_cols(nw);

    #pragma omp parallel for schedule(dynamic)
    for (int w = 0; w < nw; w++) {
        int r0 = w * 16, r1 = std::min(r0 + 16, rows);
        std::vector<int> cols(h_col_ind + h_row_ptr[r0],
                              h_col_ind + h_row_ptr[r1]);
        std::sort(cols.begin(), cols.end());
        cols.erase(std::unique(cols.begin(), cols.end()), cols.end());
        win_cols[w] = std::move(cols);
        tiles_per_win[w] = ((int)win_cols[w].size() + 7) / 8;
    }

    std::vector<int> wtp(nw + 1, 0);
    for (int w = 0; w < nw; w++) wtp[w + 1] = wtp[w] + tiles_per_win[w];
    const int nt = wtp[nw];

    std::vector<int> tile_cols((size_t)nt * 8, -1);
    std::vector<float> tile_vals((size_t)nt * 128, 0.0f);

    #pragma omp parallel for schedule(dynamic)
    for (int w = 0; w < nw; w++) {
        const std::vector<int>& cols = win_cols[w];
        int base = wtp[w];
        for (size_t i = 0; i < cols.size(); i++)
            tile_cols[(size_t)(base + i / 8) * 8 + (i % 8)] = cols[i];
        int r0 = w * 16, r1 = std::min(r0 + 16, rows);
        for (int r = r0; r < r1; r++) {
            int lr = r - r0;
            for (int e = h_row_ptr[r]; e < h_row_ptr[r + 1]; e++) {
                int lc = (int)(std::lower_bound(cols.begin(), cols.end(),
                                                h_col_ind[e]) - cols.begin());
                tile_vals[((size_t)base + lc / 8) * 128 + lr * 8 + (lc % 8)]
                    = h_values[e];
            }
        }
    }

    TCK_CHECK(cudaMalloc(&ctx->d_tile_cols, (size_t)nt * 8 * sizeof(int)));
    TCK_CHECK(cudaMalloc(&ctx->d_tile_vals, (size_t)nt * 128 * sizeof(float)));
    TCK_CHECK(cudaMemcpy(ctx->d_tile_cols, tile_cols.data(),
                         (size_t)nt * 8 * sizeof(int), cudaMemcpyHostToDevice));
    TCK_CHECK(cudaMemcpy(ctx->d_tile_vals, tile_vals.data(),
                         (size_t)nt * 128 * sizeof(float), cudaMemcpyHostToDevice));
    build_jobs(ctx, wtp);
}

// One warp per (16-row window chunk of 64, group of TC_KT k-tiles);
// warps are independent — only warp-level sync.
__global__ void task_spmm_kernel(
    const int* __restrict__ job_owner, const int* __restrict__ job_lo,
    const int* __restrict__ job_hi,
    const int* __restrict__ job_atomic,
    const int* __restrict__ tile_cols,
    const float* __restrict__ tile_vals,
    const float* __restrict__ B, float* __restrict__ C,
    int num_rows, int num_jobs) {
    const int ktg_per_win = TC_K / (16 * TC_KT);
    const int job = blockIdx.x * TC_WPB + threadIdx.y;
    if (job >= num_jobs * ktg_per_win) return;
    const int cj = job / ktg_per_win;
    const int w = job_owner[cj];
    const int koff0 = (job % ktg_per_win) * 16 * TC_KT;
    const int lane = threadIdx.x;
    const bool accum = job_atomic[cj];

    __shared__ float smem[TC_WPB * 256];
    float* sB = smem + (size_t)threadIdx.y * 256;

    const int t0 = job_lo[cj], t1 = job_hi[cj];

    wmma::fragment<wmma::matrix_a, 16, 16, 8,
                   wmma::precision::tf32, wmma::row_major> a_frag;
    wmma::fragment<wmma::matrix_b, 16, 16, 8,
                   wmma::precision::tf32, wmma::col_major> b_frag;
    wmma::fragment<wmma::accumulator, 16, 16, 8, float> acc[TC_KT];
    #pragma unroll
    for (int j = 0; j < TC_KT; j++) wmma::fill_fragment(acc[j], 0.0f);

    for (int t = t0; t < t1; t++) {
        int src = (lane < 8) ? tile_cols[t * 8 + lane] : -1;
        wmma::load_matrix_sync(a_frag, tile_vals + (size_t)t * 128, 8);
        #pragma unroll
        for (int j = 0; j < TC_KT; j++) {
            const int koff = koff0 + j * 16;
            #pragma unroll
            for (int e = lane; e < 128; e += 32) {
                int kk = e >> 4, n = e & 15;
                int row = __shfl_sync(0xffffffffu, src, kk);
                sB[n * 8 + kk] =
                    (row >= 0) ? B[(size_t)row * TC_K + koff + n] : 0.0f;
            }
            __syncwarp();
            wmma::load_matrix_sync(b_frag, sB, 8);
            tc_mma(acc[j], a_frag, b_frag);
            __syncwarp();
        }
    }

    const int r0 = w * 16;
    #pragma unroll
    for (int j = 0; j < TC_KT; j++) {
        const int koff = koff0 + j * 16;
                if (!accum && true) {
                    wmma::store_matrix_sync(C + (size_t)r0 * TC_K + koff, acc[j],
                                            TC_K, wmma::mem_row_major);
                } else {
                    wmma::store_matrix_sync(sB, acc[j], 16, wmma::mem_row_major);
                    __syncwarp();
                    int valid = min(16, num_rows - r0);
                    for (int e = lane; e < valid * 16; e += 32) {
                        int r = e >> 4, n = e & 15;
                        float v = sB[r * 16 + n];
                        if (accum) atomicAdd(&C[(size_t)(r0 + r) * TC_K + koff + n], v);
                        else C[(size_t)(r0 + r) * TC_K + koff + n] = v;
                    }
                    __syncwarp();
                }
    }
}

void* spmm_preprocess(const int* d_row_ptr, const int* d_col_ind,
                      const float* d_values,
                      int num_rows, int num_cols, int nnz, int K) {
    TaskCtx* ctx = new TaskCtx();
    ctx->num_rows = num_rows;
    ctx->num_cols = num_cols;
    ctx->nnz = nnz;
    std::vector<int> h_rp(num_rows + 1), h_ci(nnz);
    std::vector<float> h_v(nnz);
    TCK_CHECK(cudaMemcpy(h_rp.data(), d_row_ptr,
                         (num_rows + 1) * sizeof(int), cudaMemcpyDeviceToHost));
    TCK_CHECK(cudaMemcpy(h_ci.data(), d_col_ind,
                         (size_t)nnz * sizeof(int), cudaMemcpyDeviceToHost));
    TCK_CHECK(cudaMemcpy(h_v.data(), d_values,
                         (size_t)nnz * sizeof(float), cudaMemcpyDeviceToHost));
    build_condensed(ctx, h_rp.data(), h_ci.data(), h_v.data());
    return ctx;
}

void spmm_compute(void* vctx,
                  const int*, const int*, const float*,
                  const float* d_B, float* d_C,
                  int num_rows, int num_cols, int nnz, int K) {
    TaskCtx* ctx = (TaskCtx*)vctx;
    TCK_CHECK(cudaMemsetAsync(d_C, 0,
        (size_t)num_rows * TC_K * sizeof(float)));

    int jobs = ctx->num_jobs * (TC_K / (16 * TC_KT));
    dim3 block(32, TC_WPB);
    task_spmm_kernel<<<(jobs + TC_WPB - 1) / TC_WPB, block>>>(
        ctx->d_job_owner, ctx->d_job_lo, ctx->d_job_hi, ctx->d_job_atomic,
        ctx->d_tile_cols, ctx->d_tile_vals, d_B, d_C,
        num_rows, ctx->num_jobs);
}

void spmm_cleanup(void* vctx) {
    TaskCtx* ctx = (TaskCtx*)vctx;
    if (!ctx) return;
    cudaFree(ctx->d_tile_cols);
    cudaFree(ctx->d_tile_vals);
    cudaFree(ctx->d_job_owner);
    cudaFree(ctx->d_job_lo);
    cudaFree(ctx->d_job_hi);
    cudaFree(ctx->d_job_atomic);
    delete ctx;
}
